"""Original teaching additions. Sources support principles, not validated trick protocols."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
D=json.loads((ROOT/'research/base-data.json').read_text())
D['sources']=[s for s in D['sources'] if not s['id'].startswith('T')]
D['sources']+=json.loads((ROOT/'research/additional-sources.json').read_text())
D['version']=7
D['updated']='2026-10-24'
for x in D['intro']:
 x['body']=x['body'].replace('column','section').replace('Foundations records','Foundations covers').replace('Practice elsewhere records','Practice elsewhere covers')
D['intro'].append({'title':'After a difficult day','body':'Several close-together challenges can leave a dog less able to cope. Offer predictable rest, space, and enjoyable low-demand activities. Return to planned exposure only when this dog is back at their ordinary comfortable baseline; there is no universal number of hours that certifies recovery.'})
D['intro'].append({'title':'Tricks are optional','body':'Choose movements and materials that suit this dog. Use a non-slip surface, safe oversized props, and brief supervised sessions. Stop at stiffness, avoidance, strain, guarding, or frustration. Food puzzles, targets, and household jobs are enrichment, not a substitute for an anxiety treatment plan. Skip anything the dog does not enjoy.'})
for e in D['evidence']:
 if e['topic']=='Overall method':e['sources']+='; A01';e['limits']+=' The AVSAB board reaffirmed its 2021 position in 2025.'
 if e['topic']=='Source screening':e['limits']+=' A03’s “reading” title is not treated as evidence of literacy; spoken words, gestures and place cues may explain the game.'
D['evidence'] += [
 {'topic':'Clever games without inflated claims','conclusion':'Treat toy names and picture cues as enjoyable optional experiments. Swap object sides and keep body language neutral. A reliable targeting or retrieve game is valuable even without label discrimination.','limits':'Object-label studies distinguish typical dogs from exceptional word learners. Their results do not guarantee a vocabulary, rapid-learning timeline, or an intelligence ranking.','sources':'A03; A07; A08'},
 {'topic':'Practical jobs and movement','conclusion':'Use light, safe props and comfortable floor-level movement. Build component actions, then combine them into small household jobs.','limits':'These lesson sequences are original practical adaptations. Professional guides support targeting and shaping principles; no study establishes each sequence as an anxiety intervention or an exercise prescription.','sources':'P11; P20; P21; P22; P32; A02; A04; A05'},
 {'topic':'Dental participation','conclusion':'Build voluntary mouth-care participation in very small pieces. Use pet-safe materials and obtain a veterinary demonstration.','limits':'A training guide cannot diagnose oral pain, replace dental treatment, or determine which individual dog can safely have their mouth handled. Do not restrain, force the jaw, or use human toothpaste.','sources':'A06; R17; R18'}]
for s in D['sources']:
 if s['id']=='R05':
  s['url']='https://www.sciencedirect.com/science/article/pii/S0168159124001539'
  s['access']='Publisher abstract and highlights rechecked 2026-10-20. Full paper not analyzed in this review.'
  s['author']='Joanna Shnookal, Deanna Tepper, Tiffani Howell, Pauleen Bennett'
 if s['id']=='P32':s['limits']+=' Puzzles are supervised and dogs are separated when resources could cause conflict.'

# Each entry is (title, teaching guide, advancement criterion, easier/stop advice).
def add(code,title,topic,goal,cue,setup,sources,entries,deps=(),priority='Optional trick'):
 steps=[]
 for i,row in enumerate(entries,1):
  step={'id':f'{code}-{i}','title':row[0],'teach':row[1],'advance':row[2],'easier':row[3],
        'deps':list(deps) if i==1 else [[f'{code}-{i-1}',3]]}
  if len(row)>4:step['deps']=row[4]
  steps.append(step)
 D['skills'].append({'code':code,'title':title,'sheet':topic,'goal':goal,'cue':cue,'setup':setup,'sources':sources,'priority':priority,'steps':steps})

add('OTARGET','Nose target an object','Foundations','Touch a broad, safe target with the nose.','Target','A large smooth target pad on a stable handle; no sharp ends or detachable small parts.','P11; P22',[
 ('Discover the target','Hold the target still a little to the side of the dog’s nose. Let them choose to investigate. Mark a gentle nose contact and reward from your other hand. Remove the target after each attempt; do not poke it toward the face.','Voluntarily touches the still pad in 4 of 5 easy presentations.','Use a larger target, increase space, or reward a glance or small approach first.'),
 ('Add a cue and vary placement','Say “target,” then present the familiar pad. Reward nose contact. Once this is easy, change the pad’s position by a few inches, staying at a comfortable head height. Return to the easiest placement between small changes.','Touches the pad on cue in two short sessions, with 4 of 5 comfortable responses.','Keep the pad stationary and closer. Stop if the dog starts mouthing or avoiding it.')],priority='Useful extra')

add('BOW','Take a little bow','Clever companions','Offer a brief comfortable play-bow shape.','Bow','Healthy comfortable movement on a non-slip floor. Capture a natural stretch; skip for pain, stiffness, or balance concerns.','A05; R01',[
 ('Catch a natural stretch','Watch during an ordinary relaxed transition from rest. If the dog naturally stretches their front end down with the rear up, quietly mark the shape and offer a reward as they stand again. Never push the chest down or hold the back end up.','You can reward several naturally offered comfortable bows without interrupting rest.','Skip this trick if the movement is rare or uncomfortable. Do not wake or repeatedly provoke stretching.'),
 ('Invite the familiar shape','In a short playful session, wait for a small offered front-end dip and reward it. A gentle empty-hand gesture toward the space between the front paws can become a prompt if the dog willingly follows it. Release promptly rather than asking for a long stretch.','Offers a brief comfortable bow from the gesture in 4 of 5 easy opportunities.','Reward a smaller dip, reset to stand, or return to capturing. Do not place a hand under the abdomen.'),
 ('Name the bow','Say “bow” just before the familiar gesture. Mark the brief shape, release, and reward. Over several enjoyable repetitions make the gesture smaller. End after a few comfortable bows; the aim is a cheerful trick, not a flexibility exercise.','Responds to the cue plus small gesture in two short sessions without strain or prolonged holding.','Keep the original gesture or choose another trick. Stop for any stiffness or reluctance.')])

add('BACK','Back up a few steps','Body awareness','Take one to three comfortable backward steps without being crowded.','Back','Flat non-slip space with an unobstructed route; no narrow chute, leash pressure, or approach into the dog.','P11; P22; R01',[
 ('Reward a backward foot shift','Begin with the dog standing comfortably in open space. After an ordinary reward, watch for a voluntary small backward weight shift or foot movement as they reset. Mark it immediately and deliver the next reward where they can remain balanced. Stay still rather than stepping into them.','Offers several small backward foot movements without sitting, scrambling, or being crowded.','Reward a weight shift first, keep sessions very short, or skip if the dog cannot find a comfortable movement.'),
 ('Build one clear step','Reward the familiar backward shift, then wait for a slightly larger movement that places one foot back. Mark that movement and reward. Once a clear step is offered, say “back” just before it. Keep your own feet stationary and the route open.','Takes one voluntary step back on the emerging cue in 4 of 5 easy attempts.','Return to a tiny shift. Check the surface and stop for stiffness or confusion.'),
 ('Add a second step','Cue one known backward step, then briefly wait for a second before marking and rewarding. Mix one-step rewards with occasional two-step attempts. Only later invite three slow steps. This is a short positioning game, not a speed or endurance drill.','Offers two or three balanced steps on cue in two short sessions.','Reward the first step again. Do not chase the dog backward or practice near edges.')])

add('MIDDLE','Stand between your legs','Clever companions','Choose a roomy position between your stationary legs.','Middle','Only if the dog fits with generous clearance and the handler is steady; otherwise use a cone game.','A04; P11',[
 ('Make one comfortable pass','Stand with a stable, comfortably wide stance. Offer a familiar hand target so the dog can choose to pass straight through the open space. Reward after they emerge. Keep your legs still and never close them around the dog.','Makes relaxed straight passes with no ducking, squeezing, or hesitation.','Use two widely spaced cones instead, or reward approaching the opening without passing.'),
 ('Pause in the middle','Use a target to guide a familiar easy pass, then reward when the dog is centered between your still legs. Feed at a comfortable forward head position, release after a moment, and let them walk out. Add “middle” before the familiar invitation.','Enters and pauses briefly on cue in 4 of 5 relaxed opportunities.','Reward a complete pass without stopping. Skip if close body space worries either participant.')],deps=[['TOUCH-2',2]])

add('WEAVE','A slow figure eight','Clever companions','Walk a gentle stationary figure eight around your legs.','Weave','Generous body clearance and a steady handler; wide curves only. Cone figure eights are an alternative.','A04',[
 ('Make one roomy loop','With your feet still and wide, use the known hand target to invite a comfortable pass, then a broad curve around one leg back to the front. Reward partway at first, then after one complete loop. Avoid wrapping tightly against the knee or dog’s body.','Completes one smooth unhurried loop without squeezing or physical steering.','Make a larger curve or use a cone. Stop if the handler must balance or move abruptly.'),
 ('Learn the other loop','Practice a separate roomy loop around the other leg using the other hand target. Reward that loop on its own until it is familiar. Alternate which side starts, but do not link the loops yet if either direction feels awkward.','Offers either single loop comfortably from its hand signal in two short sessions.','Practice the easier side once and finish; reduce bending demands rather than drilling the difficult side.'),
 ('Join the figure eight','Guide one familiar loop and switch to the other target for the second. Reward after the first loop if needed, then after both when joining is easy. Add “weave” before the first signal. Keep the sequence slow and end with an easy release.','Completes one comfortable figure eight from the cue and small hand signals in 4 of 5 easy attempts.','Reward each loop separately or return to cone loops. No fast repetitions or tight turns.')],deps=[['MIDDLE-1',3]])

add('CONE','Go around a cone','Body awareness','Walk a broad loop around one floor marker.','Around','A stable soft cone or broad safe object; clear non-slip space.','P11; P22',[
 ('Follow a wide arc','Place the cone several feet away in clear space. Use a known hand target to invite the dog along a broad half-circle around it. Reward at the far side, then guide the remaining half. Keep the curve wide enough for ordinary walking without twisting.','Comfortably completes the loop with two reward points and no contact with the cone.','Use a smaller arc, more space, or remove a novel cone until the dog is comfortable.'),
 ('Join and name the loop','Use the familiar arc with fewer target presentations until the dog can walk the whole loop before the reward. Say “around” before the gesture. Gradually reduce your own movement while keeping the cone close and the route broad.','Walks one full broad loop from a cue and gesture in 4 of 5 easy attempts.','Walk with the dog again or reward halfway. Transfer to other places belongs in separate easy practice.')],deps=[['TOUCH-2',2]])

add('CONEEIGHT','Figure eight around two markers','Body awareness','Join two broad cone loops into one smooth figure eight.','Eight','Two soft stable markers spaced generously apart; comfortable walking only.','P11; P22',[
 ('Practice each separate loop','Place two familiar markers far enough apart for a wide walking curve. Cue a known loop around one, reward, and pause. Practice the other marker separately. Use a hand target for help rather than tightening the dog’s path with your body.','Can complete either separate broad loop comfortably with clear signals.','Increase the gap or return to one marker. Skip tight turns or repetitive bending.'),
 ('Connect the loops','Guide one easy loop, then point through the open center toward the second marker for another loop. Reward in the center at first. As joining becomes easy, reward after the whole figure eight and add your chosen cue before starting.','Completes a slow broad figure eight with comfortable movement in two short sessions.','Reward the center transition, use a bigger layout, or return to separate loops.')],deps=[['CONE-2',3]])

add('FEET','Front paws on a flat target','Body awareness','Place both front feet on a stable floor mat.','Feet','A broad non-slip mat lying flat, with no raised or unstable platform.','P11; P22',[
 ('Find one paw contact','Lay the mat flat in an open room and let the dog investigate. Mark any voluntary front-paw contact and deliver a reward while the paw is still there if comfortable. Release or toss a nearby reset reward so the dog can choose another approach.','Voluntarily places at least one front paw on the mat on several approaches.','Use a larger mat or reward approaching it. Never lift a paw or pull the dog onto it.'),
 ('Reward two front paws','When one-paw contacts are easy, reward approaches that bring both front paws onto the broad mat. Deliver food at a comfortable natural head height so the dog can stand balanced. Keep all feet on the floor and release after a brief moment.','Offers both front paws on the mat in 4 of 5 easy approaches.','Reward one paw again, enlarge the target, or stop for any uneven or uncomfortable movement.'),
 ('Add the floor-target cue','Say “feet” before the familiar invitation toward the mat. Mark two front paws, reward, then release. Fade pointing a little at a time. The goal is this safe flat target; raising it or adding unstable surfaces is not part of this lesson.','Places both front feet on the familiar floor target from the cue in two short sessions.','Keep the clear gesture or larger target. Do not progress to balance equipment without individual guidance.')])

add('HOOP','Walk through a floor-level hoop','Body awareness','Choose to walk through a large opening without jumping.','Through','A very wide smooth hoop held stationary with its bottom resting on the floor; no collars or tags that can snag.','P11; P22; R01',[
 ('Explore the open shape','Keep the hoop still with its bottom on the floor and plenty of room to go around it. Reward a glance or approach. If comfortable, offer a hand target through the center and reward one voluntary step through. Never move the hoop over the dog.','Walks through the large opening comfortably while it stays stationary on the floor.','Use a wider opening or stop at looking. Avoid hoops if tags, equipment, or body shape could snag.'),
 ('Name the walking pass','Say “through” before the familiar target invitation. Reward after the dog walks fully through. Gradually reduce your hand movement while the hoop remains on the floor. Reset away from it so each pass is voluntary rather than a repetitive obstacle circuit.','Makes a relaxed walking pass on cue in 4 of 5 attempts across two short sessions.','Use the target again or end. This lesson does not add height, jumping, or narrow openings.')],deps=[['TOUCH-2',2]])

add('TUNNEL','Explore an open tunnel','Body awareness','Choose a short, wide, secured open tunnel.','Tunnel','A wide rigid/open-ended dog tunnel secured against rolling; start extremely short or fully open. A helper may steady equipment, never hold the dog.','P11; P22; R01',[
 ('Explore without entering','Set the tunnel where the dog can investigate and walk away. Reward looking or approaching the entrance, with rewards placed outside first. Keep the interior bright and the far end visible. If the dog avoids it, simply give more space and finish there.','Approaches the entrance with ordinary loose movement and freely leaves and returns.','Use a large open arch instead. Do not lure an uneasy dog inside or block the exit.'),
 ('Take one voluntary short pass','Use the shortest open version with your reward hand visible just beyond the other end. Let the dog choose a straight walking pass and reward after they emerge. Reset outside. Keep the tunnel fixed and do not touch or move it while the dog is inside.','Chooses several relaxed short passes without crouching, rushing, freezing, or scrambling.','Shorten or widen the opening. Skip if a comfortable version is unavailable.'),
 ('Add a cue before the pass','Say “tunnel” before the familiar easy invitation. Reward each voluntary pass, then reduce the invitation slightly. Only add a tiny amount of straight tunnel length when both ends remain obvious. Keep curved, long, dark, or collapsible fabric tunnels outside this plan.','Comfortably enters the familiar short open tunnel on cue in two easy sessions.','Return to the shorter version or a floor-level hoop; no pushing, chasing, or trapping.')])

add('NOSEBALL','Roll a ball with the nose','Clever companions','Nudge a safe large ball along the floor.','Push','A lightweight ball far too large to swallow; clear flat non-slip floor; no hard or tiny balls.','A02; P11',[
 ('Find a gentle nose touch','Hold the large ball still just below natural nose height. Mark a voluntary nose touch and reward from your other hand. Keep the ball steady and reward gentle contact rather than grabbing. If the dog prefers to bite it, choose a larger ball or another game.','Offers gentle nose contacts in 4 of 5 comfortable presentations.','Use a familiar target on the ball’s near side or reward a glance. Stop if the ball worries them.'),
 ('Let a small nudge move it','Rest the ball on the floor against your foot so it cannot roll far. Reward a nose touch, then let a tiny nudge move it an inch or two. Reset calmly. Gradually allow a slightly longer roll without encouraging chasing or pouncing.','Uses the nose to roll the ball a short distance several times without grabbing or frantic chasing.','Stabilize it again or reward a stationary touch. Use an even lighter oversized ball.'),
 ('Cue one short roll','Say “push” before the familiar nudge. Mark and reward a short floor roll, then stop the ball and reset. Gradually fade your pointing so the cue and ball presentation invite the action. Keep the reward close and the activity slow.','Produces one controlled nose roll on cue in two short sessions.','Return to one tiny movement. End before the game turns into intense chasing.')])

add('BOWL','Dog bowling','Clever companions','Nudge a large ball toward a few soft lightweight pins.','Bowl','Known ball push; two or three soft pins that fall quietly; no chewable small pieces.','A02',[
 ('One quiet pin','Place one soft pin close behind the known ball, leaving a straight easy route. Cue the familiar nose roll. Reward movement toward the pin even if it misses; separately reward comfortable responses to a quiet fall. Reset the pin yourself after each attempt.','Rolls toward the nearby pin and stays comfortable when it falls softly.','Remove the pin or make it quieter. Return to stationary ball touches if the fall startles the dog.'),
 ('A small bowling lane','Arrange two or three familiar quiet pins in a wide close cluster. Put the ball on the easy straight route and cue one roll. Mark a roll into the cluster, reward, and reset. Increase distance only slightly once aiming is comfortable.','Makes several purposeful short rolls toward the soft pins, with comfortable resets and no grabbing.','Use one closer pin or reward near misses. Winning a strike is optional; enjoyment is the criterion.')],deps=[['NOSEBALL-3',3]])

add('GOAL','Score a gentle goal','Clever companions','Nose-roll a safe ball between two floor markers.','Goal','Two widely spaced soft markers and a known oversized ball; no nets or entanglement hazards.','A02; P11',[
 ('A wide nearby opening','Set two soft markers far apart just beyond the ball. Cue a short familiar nose roll toward the open gap and reward movement into it. Start close enough that aiming is easy; do not ask for a chase, forceful impact, or several pushes in a row.','Comfortably rolls the ball through the wide nearby gap several times.','Widen the goal or move it closer. Reward a roll toward the gap first.'),
 ('Name the little game','Say “goal” before the familiar push cue, then gradually use the new cue with a small pointing gesture. Reward one successful short roll and reset. If desired, move the start position a few inches; treat that as a separate small adjustment.','Offers one controlled roll toward and through the familiar opening on cue in two sessions.','Return to a close wide goal and known push cue. No need for harder shots or prolonged repetitions.')],deps=[['NOSEBALL-3',3]])

add('HIGHFIVE','Low high five','Clever companions','Briefly touch a low open palm with a front paw.','High five','A stable comfortable position; hand kept below the dog’s elbow, with no paw pulling.','P11; P22',[
 ('Change the paw target','Offer the familiar paw invitation with your palm more upright but still low. Mark a light voluntary paw contact and reward. Remove your hand after a moment rather than holding the paw. Reward a small lift if the changed hand shape is puzzling.','Makes gentle low palm contact without leaning, twisting, or having the paw held.','Return to the known paw cue and horizontal hand. Skip if balancing on three legs is uncomfortable.'),
 ('Add the new cue','Say “high five” before presenting the low upright palm. Mark the brief touch, lower your hand, and reward. Gradually reduce the older paw prompt. Keep the hand low; the name of the trick does not require lifting the limb high.','Offers a brief low paw touch in 4 of 5 easy invitations across two short sessions.','Keep the clearer old signal or reward a smaller lift. Do not repeat through fatigue.')],deps=[['PAW-1',3]])

add('WAVE','A little wave','Clever companions','Offer one small paw lift without hand contact.','Wave','Comfortable balanced position and known low high five; no repeated high paw lifts.','P11; P22',[
 ('Reward the lift before contact','Invite the familiar low high five. As the paw begins to lift, mark before it reaches your palm, lower your hand away, and reward. Keep the movement small so the dog does not stretch or paw at your arm. Reset between attempts.','Offers a small comfortable paw lift when shown the familiar hand signal.','Reward ordinary low palm contact again. Do not withdraw the hand so fast that the dog overreaches.'),
 ('Name one small wave','Say “wave,” give a smaller version of the familiar signal, and reward one short lift. Gradually hold your signal farther from the paw while still easy to understand. One lift is enough; repeated waving and elevated holds are not required.','Responds to cue and small signal with a balanced low paw lift in two short sessions.','Return to low high five or choose a nose-target trick if paw lifting is uncomfortable.')],deps=[['HIGHFIVE-2',3]])

add('RESTHEAD','Rest the head on a cushion','Calm at home','Place the chin briefly on a low comfortable cushion.','Rest','A low stable soft cushion; no lifting or positioning the head. Chin placement is not proof of relaxation.','P23; R18',[
 ('Discover the cushion target','Place the cushion at a comfortable natural chin height with the dog able to leave. Mark any voluntary chin contact and reward gently beside it. A known chin-rest invitation can help, but never lift or press the head into position.','Voluntarily lowers the chin onto the cushion several times without tension or restraint.','Use a flatter cushion, reward a small head dip, or return to a familiar hand chin rest.'),
 ('Name a brief rest','Say “rest” before the familiar voluntary chin placement. Reward a moment of soft contact, then invite a break. Add only a second when comfortable. Keep observing the whole dog: a chin on a cushion can be an action without emotional calm.','Places and briefly rests the chin on the cushion on cue while freely lifting away.','Shorten contact or skip the cue and reward spontaneous comfortable resting instead.')],deps=[['CHIN-1',2]],priority='Useful extra')

add('POSE','A comfortable photo pose','Clever companions','Hold a chosen comfortable position for a quick photo.','Pose','Use a known comfortable sit or stand; no costumes, forced handling, flash, or startling props.','P17; P11',[
 ('A very short still moment','Invite a comfortable familiar sit or stand. Mark a brief still moment and reward before your dog needs to move. Hold the phone down at first and reward comfort with it being present. Keep looking at your dog rather than repeatedly rearranging them.','Offers one or two comfortable still seconds with the ordinary phone present.','Use stand instead of sit, keep the phone farther away, or reward any comfortable pause.'),
 ('Pair a quiet photo with a cue','Say “pose” before the familiar position signal. Reward a brief pause, then take one silent no-flash photo and release. On later attempts reward immediately after the photo. Keep the phone’s motion small and give the dog a choice to finish.','Comfortably pauses for one quick no-flash photo in several easy attempts.','Return to phone presence without taking a picture. A photo is never worth extending discomfort.')])

add('BUTTON','Press a large quiet button','Useful little jobs','Press a broad stable pad with the nose.','Button','A large low-force muted training button or inert practice pad; no cables, batteries, small parts, or startling sound within reach.','P11; P22',[
 ('Target the pad','Keep the pad stable at a comfortable nose height. Reward voluntary nose contact, as with an ordinary object target. Choose a target too large to mouth or swallow and keep any electronic mechanism inaccessible. Teach with the sound disabled first.','Touches the stable pad with a relaxed nose on several presentations.','Use a flat inert pad or ordinary target. End if the dog paws, mouths, or avoids it.'),
 ('Add only gentle pressure','Reward touches that slightly depress the low-force pad. Mark as the surface moves and reward from the other hand. If pressure is difficult, use a more sensitive pad rather than asking the dog to push harder or brace their neck.','Produces a gentle clear press repeatedly without strain, grabbing, or startle.','Return to light touch on an inert pad. No hard switches or forceful repeated pushes.'),
 ('Use the designated button cue','Say “button” before offering the familiar pad. Reward one press and reset. Fade pointing while the pad remains in its familiar position. Optional sound is a separate gradual comfort lesson; this action alone is not evidence of language or a request.','Gently presses the designated pad on cue in two short sessions.','Keep it muted and use the old target cue. Skip sound if noises are a concern.')],deps=[['OTARGET-2',2]])

add('SLIPPERS','Bring a designated slipper','Useful little jobs','Fetch one safe training slipper into your hand.','Slipper','A clean light oversized slipper with no loose parts; skip for dogs that shred, swallow fabric, or guard items.','P20; P21',[
 ('Make the safe prop familiar','Present the designated slipper as a training prop and invite a known take. Reward a gentle hold, then ask for the familiar give into your hand. Use one supervised prop consistently; do not encourage searching the household for other shoes.','Takes and gives the designated prop gently without chewing, guarding, or tugging.','Use a familiar safe toy instead. Stop if any part could be swallowed or the dog guards it.'),
 ('Pick it up nearby','Place the slipper on a clear non-slip floor close to your feet. Invite a known pickup and delivery, then reward the give into your hand. If needed, practice the pickup alone before asking for the return. Reset yourself after every attempt.','Picks up and gives the nearby prop in 4 of 5 easy opportunities.','Bring it closer or present it at hand height again. Reward smaller comfortable parts.'),
 ('Retrieve from one designated spot','Put the slipper on an obvious low mat a few steps away. Say “slipper” before the familiar retrieve invitation. Reward delivery, then return it to that same spot. Increase only a step at a time and keep all other footwear out of the game.','Retrieves this prop from its designated easy spot and gives it to you in two sessions.','Return to a shorter distance or a safe toy. General household scavenging is not part of this job.')],deps=[['FETCH-2',3],['GIVE-1',3]])

add('POUCH','Carry a little pouch','Useful little jobs','Carry a safe light message pouch a short distance.','Carry pouch','A soft oversized empty pouch with a broad safe grip; no straps that can loop over the head and no contents to ingest.','P20; P21',[
 ('Take and return the empty pouch','Offer the familiar safe grip area and cue a known take. Mark a gentle hold, then ask for give and reward. Keep the pouch empty while introducing its feel. The dog should not need to grip a zipper, buckle, or narrow cord.','Takes, gently holds, and gives the empty pouch with no chewing or worry.','Use an ordinary safe retrieve toy. Remove straps or choose a different prop.'),
 ('Carry toward a nearby hand','Offer the empty pouch, take one slow step back, and invite the familiar give into your hand. Reward after delivery. Build only a few steps, keeping the pouch off the ground and the route clear without asking for a prolonged hold.','Comfortably carries the empty pouch a few steps and gives on cue.','Return to a stationary give or one step. Stop if the load or grip changes natural movement.'),
 ('One light protected note','If the pouch is designed to stay closed and your dog is not a shredder, add a single protected paper note with no staples or clips. Repeat the familiar short carry. The human handles opening and closing; the dog only transports the safe prop.','Carries the very light closed pouch and gives it reliably without chewing or inspecting the contents.','Keep it empty or use a toy messenger game. Never add medication, valuables, or heavy contents.')],deps=[['CARRY-1',3],['GIVE-1',3]])

add('MESSENGER','Deliver to a familiar person','Useful little jobs','Carry a safe toy or pouch to one cooperative familiar adult.','Deliver','Two trusted adults close together; a safe carry prop; no guarding or tension around people.','P20; P21; P11',[
 ('Give to the second adult','Have the familiar helper sit or stand nearby without reaching over the dog. Let them invite the known give into an open low hand and reward the delivery. Begin while you are still beside the dog so no departure or stranger approach is involved.','Comfortably gives the safe prop to the familiar helper without guarding or hesitation.','Use the usual person for give first. Stop if hand approaches or item possession creates tension.'),
 ('Carry one step toward the helper','Offer the familiar safe prop, then let the nearby helper invite delivery with the known open hand. Reward after the give. Start one step apart and gradually make it a few steps, with both people still visible and relaxed.','Carries and gives to the nearby helper on their invitation in several easy attempts.','Bring the helper closer, use a safer toy, or practice separate give repetitions again.'),
 ('Start the message job','Say “deliver” before the helper’s familiar invitation. Gradually make their hand signal smaller while keeping them clearly visible. Reward the give and celebrate with a quiet break. This is a specific cooperative game, not permission to approach unfamiliar people with objects.','Completes the short take–carry–give sequence to this familiar helper in two sessions.','Return to one-step delivery or ordinary toy fetch. Do not use the game to force social contact.')],deps=[['CARRY-1',3],['GIVE-1',3]])

add('LAUNDRY','Place safe cloths in a basket','Useful little jobs','Move designated clean training cloths into a low open basket.','Laundry','Large safe clean cloth props and a stable low basket; no socks, detergent, dirty laundry, strings, or ingestible fabric for shredders.','P21; P20',[
 ('One cloth over the basket','Offer the safe training cloth just above a wide low basket. Ask for a known take and drop so the cloth falls inside. Mark the drop and reward. Keep hands still and do not pull the cloth from the dog’s mouth.','Drops the designated cloth into the basket comfortably several times.','Use a safe familiar toy or widen the basket. Skip fabric if chewing or swallowing is likely.'),
 ('Pick up beside the basket','Place the same cloth on the floor touching the basket’s outside edge. Invite pickup, then the familiar drop over the rim. Reward that delivery. Practice one cloth at a time, making the path only long enough to connect pickup and drop.','Picks up the nearby cloth and deposits it into the basket in 4 of 5 easy attempts.','Hold the cloth above the basket again, or practice a separate floor pickup first.'),
 ('Gather a small visible set','Place two designated cloths a little apart near the basket. Cue “laundry” for one pickup and deposit, reward, then start a new invitation for the second. Build only short visible routes; humans handle all actual laundry products and appliance access.','Makes two separately cued comfortable deposits from nearby spots without chewing or guarding.','Return to one cloth beside the basket. No repeated drilling or access to laundry machines.')],deps=[['BOX-2',3]])

add('TOYNAME','Give one toy a name','Clever companions','Build a playful association with one designated toy’s label.','A distinct toy name','One safe favorite toy in a quiet room; this experiment is optional and does not test intelligence.','A07; A08; P20',[
 ('Use the label during play','Choose one short label for the favorite toy. Say it once as you present the toy for a brief game the dog already enjoys. Repeat on separate playful occasions, not in a long naming drill. Keep other toys out of these initial pairings.','The dog enjoys repeated brief label-and-toy play pairings without frustration.','Use ordinary unnamed play. Object labels are difficult for many dogs, and this is entirely optional.'),
 ('Request that one familiar toy','Put only the named toy nearby on a clear floor. Say its label once, then invite the familiar pickup if needed. Reward delivery or a clear approach. Gradually reduce the pickup gesture while moving the toy to a few obvious nearby spots.','Approaches or retrieves the single named toy from several easy nearby placements. This does not yet establish label discrimination.','Return to playful pairings or ordinary fetch. Do not claim understanding from a one-object setup.')],deps=[['FETCH-2',2]])

add('TWOOBJECT','An optional two-toy choice','Clever companions','Explore whether two toy labels guide choices without position or pointing cues.','Two different toy labels','Two safe familiar toys with distinct labels; neutral body position; optional helper to place objects.','A07; A08',[
 ('Build the second toy association','Use a second distinct safe toy and its own short label during enjoyable brief play, just as for the first. Practice each toy separately in varied easy positions. Keep sessions playful and stop if the dog appears to be guessing repeatedly or becoming frustrated.','Both toys have enjoyable separate label pairings and easy single-toy approach or retrieve practice.','Continue ordinary toy play with either object. There is no deadline for learning labels.'),
 ('Offer a fair close choice','Place both familiar toys a short equal distance away, then stand centered with still hands and neutral gaze. Say one label once. Reward the requested choice; after an error, reset to an easy single-toy success rather than correcting or repeatedly testing.','Shows several comfortable choices that appear related to the requested label, with no pressure or escalating errors.','Return to one toy and playful pairings. Frequent errors are information, not disobedience.'),
 ('Check sides and human cues','Use a helper to swap toy sides between easy trials while you remain centered. Request each label in a mixed order, avoiding a predictable left–right pattern. Record choices before interpreting success. If side preference or gestures explain the choices, keep the game as ordinary fetch.','Across two brief mixed-position sets, most choices follow the requested label rather than side or pointing. No vocabulary or intelligence claim follows from this small check.','Reduce tests or stop if enjoyment drops. Gifted word-learning research does not promise this ability in every dog.')],deps=[['TOYNAME-2',3]])

add('CARDS','Respond to picture cue cards','Clever companions','Explore two visual symbols as cues for already known actions.','Two bold distinct picture cards','Large cards held still; two comfortable known actions such as sit and nose touch. This is visual cue learning, not reading language.','A03; P11; P17',[
 ('Pair one symbol with one known action','Show a large simple circle card briefly, then give the familiar cue for a comfortable known sit or stand. Reward the action and put the card away. After several easy pairings, pause briefly after showing it to see whether the action is offered before the old cue.','The first card begins to prompt its paired known action without repeated verbal requests.','Keep the usual verbal cue or stop the experiment. Never physically position the dog.'),
 ('Pair the other symbol separately','On separate easy repetitions show a very different symbol, such as thick stripes, before a familiar nose-touch cue. Reward the known touch and remove the card. Keep the picture-to-action pairing consistent; do not add novelty, distance, or distracting settings yet.','The second symbol begins to prompt its separate familiar action in a comfortable easy setup.','Use more distinct large symbols or return to ordinary cues. Avoid piling up unsuccessful guesses.'),
 ('Alternate without hidden help','Present one card at a time in the same central position and a mixed order. Keep voice, posture, and hand position neutral until the dog responds. Reward the paired action. If the old cues are still doing the work, keep practicing or choose a simpler trick.','Usually offers the paired action for each card across two brief mixed-order sessions. This is not evidence of literacy.','Re-pair each symbol separately. Any enjoyable learning is sufficient; no tests under pressure.')],deps=[['TOUCH-2',3]])

add('BOXFIND','Search a few open boxes','Scent adventures','Find a safe food reward among a few open containers.','Search','Wide shallow open boxes without staples or loose pieces, suitable food, and one dog at a time; supervise and skip for paper eaters.','P32; R12',[
 ('One obvious open box','Place a reward visibly in one shallow open box while the dog watches from nearby. Let them approach and eat it without needing a sit or nose hold. Repeat with easy placements and allow the dog to leave. The box is an invitation, not a barrier.','Comfortably approaches the box and finds the obvious food without chewing the container or climbing in.','Use a plate or floor scatter instead if boxes cause concern or chewing.'),
 ('Two separated containers','Arrange two familiar shallow boxes with space to walk around them. Let the dog watch you bait one, then invite a search. Reward discovery by letting them eat the food. Swap which box is baited and keep the task easy enough to avoid frantic digging.','Uses relaxed investigation to find the food in either familiar open box.','Reduce to one box or show the reward again. Remove unsafe or chewed materials immediately.'),
 ('A tiny hidden search','With the dog occupied comfortably nearby, place a small reward in one of three open boxes. Invite a search without pointing toward the right box. Keep containers open and accessible, and help by making the reward easier to notice before frustration develops.','Investigates the small array willingly and finds rewards with ordinary sniffing and comfortable movement.','Use fewer boxes, visible food, or plain ground search. Finding food is enrichment, not a clinical anxiety score.')],deps=[['SEARCH-1',2]],priority='Enrichment')

add('TOWEL','Unfold a loose food towel','Scent adventures','Find food under one loose towel fold.','Find it','A clean flat towel, suitable food, and close supervision; skip if fabric is chewed, swallowed, or guarded.','P32',[
 ('Food on the open towel','Lay a clean towel flat on a non-slip floor and place a few rewards on top where they are easy to see. Let the dog sniff and eat while you supervise. Remove the towel if chewing starts; no pulling, tying, or rolling is needed.','Eats the easy visible food with relaxed sniffing and no fabric chewing.','Use a suitable food mat or ordinary floor search instead.'),
 ('One very loose fold','Cover one reward with the towel’s edge, leaving part visible and a broad open route to reach it. Let the dog nudge the loose fold aside. Help promptly if it becomes frustrating. Keep the rest of the towel open and remove it when the game ends.','Comfortably finds rewards under one loose fold without grabbing or swallowing fabric.','Leave more food visible or keep the towel completely flat. Do not add knots or tight rolls.')],priority='Enrichment')

add('LOSTTOY','Find a partly hidden toy','Scent adventures','Search for a safe familiar toy in easy nearby hiding places.','Find your toy','A safe favorite toy and an uncluttered room; no high shelves, tight spaces, or forced waits.','P32; P20',[
 ('Watch an easy placement','Let the dog see you place their familiar toy beside a clear floor marker. Invite them to find it and enjoy a short familiar play or give-and-reward game. Move the marker a little between attempts so the toy remains obvious and accessible.','Willingly locates the visible toy and enjoys the reward or play afterward.','Keep the toy at your feet or use ordinary fetch. Do not force a wait while hiding it.'),
 ('Hide only a small part','Place the toy partly behind a wide safe object with most of it still visible. Invite the search and remain neutral. When the dog finds it, reward with the play they enjoy. Increase concealment only a little and help before they give up or become frantic.','Investigates and finds several easy partly hidden placements with comfortable enthusiasm.','Show more of the toy or return to a visible placement. Avoid inaccessible or surprising hiding spots.')],priority='Enrichment')

add('TRAIL','Follow a short food trail','Scent adventures','Follow a few easy spaced food rewards along a safe route.','Trail','A clean safe surface, suitable food and no other dogs competing; avoid unknown outdoor foods or unsafe ground.','P32; R12',[
 ('A visible short trail','Place a few suitable rewards a short paw-step apart on safe ground while the dog watches. Invite them to investigate the first and let them find the rest at their own pace. Walk alongside without steering their nose or pulling on equipment.','Follows the short visible line with comfortable sniffing and no frantic searching.','Use fewer rewards closer together, or choose an indoor floor search.'),
 ('One easy bend','Create a similarly short reward trail with one broad bend and a clearly accessible finish. Keep reward spacing easy and the route away from hazards. Let the dog choose the pace and stop when the small trail is finished; this is not a tracking test.','Enjoys following a short bent trail independently on a familiar safe surface.','Straighten or shorten the route. Food trails are enrichment, not proof of scent-tracking expertise.')],priority='Enrichment')

add('HIDESEEK','Find a familiar person','Scent adventures','Locate one trusted person who is only slightly out of view.','Find them','Two familiar cooperative adults, clear exits and a dog comfortable with brief visual separation; skip for separation distress.','P32; P15',[
 ('Find the visible helper','Have the familiar helper stand a few steps away, quietly invite the dog over once, and reward the approach. Begin with both people visible. Let the dog move voluntarily; this is a cheerful person-finding game, not a restraint-and-release recall drill.','Comfortably approaches the visible helper and enjoys their reward or play.','Keep the people closer. Stop if leaving either person causes worry.'),
 ('A tiny partly hidden position','Let the dog see the helper step partly behind a wide doorway while remaining mostly visible. Say “find them” and let the helper make one gentle invitation if needed. Reward finding them. Reset with everyone together before trying again.','Willingly finds the partly visible helper without distress or frantic searching.','Keep the helper fully visible and closer. Do not use hiding to test separation tolerance.'),
 ('One easy out-of-view spot','After comfortable partial hides, let the helper step just behind the same open doorway. Keep the route clear and the absence momentary. Invite finding them and help immediately with a gentle voice if needed. Reward, reunite, and end after a few enjoyable turns.','Finds the nearby familiar helper with comfortable searching and quick ordinary recovery.','Return to partial visibility or skip. No closed doors, unfamiliar people, or prolonged hidden waits.')],priority='Enrichment')

add('TEETH','Voluntary toothbrushing preparation','Care and equipment','Build comfortable participation in gentle veterinary-guided mouth care.','Ready? (an invitation)','Veterinary clearance for any dental pain; a demonstrated technique, pet-safe paste and soft suitable brush. No human toothpaste or forced jaw opening.','A06; R18',[
 ('Comfort with the care items','Let the dog see the soft brush at a comfortable distance and reward relaxed interest. Separately offer a tiny taste of veterinarian-approved pet toothpaste if suitable. Keep hands away from the mouth while building pleasant associations with the items.','Comfortably sees the brush and voluntarily accepts the chosen pet-safe taste if used.','Remove the paste, increase brush distance, or ask the veterinary team about discomfort or suitable materials.'),
 ('Invite a tiny lip touch','Ask your veterinary team to demonstrate a suitable safe approach. When the dog voluntarily offers their familiar chin rest or other agreed start signal, briefly touch the outer lip area as demonstrated, remove your hand, and reward. Stop immediately if the dog withdraws.','Freely offers repeated start signals and stays comfortable with a momentary gentle lip-area touch.','Return to hand movement at a distance. Pain, guarding, or resistance calls for individual help, not holding the head.'),
 ('One gentle outside-tooth stroke','Following the veterinary demonstration and only after comfortable lip-area work, use the soft pet brush for one gentle brief stroke on an accessible outer tooth surface. Stop, reward, and offer a break. Add tiny amounts of brushing only while participation remains voluntary.','Comfortably accepts one gentle demonstrated stroke and willingly returns for another invitation. Full brushing is built gradually with veterinary guidance.','Return to brush presence or lip-area work. Stop for pain, bleeding, tension, avoidance, or any need for restraint.')],deps=[['CHIN-1',2]],priority='Useful extra')

add('SCALE','Comfort on a floor scale','Care and equipment','Choose to stand on a stable low scale surface.','Scale','A broad stable non-slip low veterinary or pet scale, secured against wobbling; no elevated platform or forced placement.','P11; R17; R18',[
 ('Explore the low surface','Let the dog investigate the secured scale while it is still and quiet. Reward comfortable looking or approaching from the floor. A large flat mat beside it can make the area familiar. Do not lure an uneasy dog onto a moving or slippery surface.','Approaches the stable scale with loose ordinary movement and freely moves away and returns.','Begin with an ordinary floor mat and ask the clinic about a broader non-slip surface.'),
 ('Choose a step on and off','Reward a voluntary front-foot step onto the wide low surface, then invite an easy step off. Build to all four feet only if the surface stays stable and the dog moves comfortably. Never lift paws or use the leash to position the body.','Chooses to step on and off the broad low scale with all feet comfortably supported.','Reward a smaller step or return to a flat mat. Stop for wobbling, hesitation, or pain.'),
 ('A brief weigh-in pause','Say “scale” before the familiar approach. Reward a short comfortable stand, then release off the scale before the dog needs to shift. Add just enough time for the reading while the person stays quiet. Other clinic handling is a separate cooperative-care lesson.','Voluntarily steps on and briefly stands long enough for a reading in two comfortable practice sessions.','Release sooner, reward entry only, or work with the clinic on an easier weighing setup.')],priority='Useful extra')

